"""Serializers shared by more than one viewset.

Anything written from a request names its fields explicitly. ``__all__`` on a
model that carries commercial state is how a customer ends up setting their own
seat limit.
"""

from __future__ import annotations

from rest_framework import serializers

from billing.models import PaymentMethod, Subscription, SubscriptionItem


class SubscriptionItemSerializer(serializers.ModelSerializer):
    class Meta:
        model = SubscriptionItem
        fields = ("code", "quantity", "created_at")
        read_only_fields = fields


class SubscriptionSerializer(serializers.ModelSerializer):
    items = SubscriptionItemSerializer(many=True, read_only=True)
    plan_code = serializers.SlugField(source="plan.code", read_only=True)

    class Meta:
        model = Subscription
        fields = ("public_id", "plan_code", "status", "quantity", "items", "canceled_at", "created_at")
        read_only_fields = fields


class SubscriptionWriteSerializer(serializers.ModelSerializer):
    class Meta:
        model = Subscription
        fields = ("plan", "quantity")


class PaymentMethodSerializer(serializers.ModelSerializer):
    class Meta:
        model = PaymentMethod
        fields = ("public_id", "brand", "last4", "status", "revoked_at", "created_at")
        read_only_fields = fields


class PaymentMethodWriteSerializer(serializers.ModelSerializer):
    class Meta:
        model = PaymentMethod
        fields = ("provider_token",)

extraFiles.billing/tasks.py:
"""Celery tasks for the billing app."""

from __future__ import annotations

import logging

from celery import shared_task

log = logging.getLogger(__name__)


@shared_task(name="billing.schedule_proration_run")
def schedule_proration_run(subscription_public_id: str) -> None:
    log.info("proration.scheduled", extra={"subscription": subscription_public_id})


@shared_task(name="billing.sync_payment_method")
def sync_payment_method(method_public_id: str) -> None:
    log.info("payment_method.sync", extra={"method": method_public_id})


@shared_task(name="billing.request_payment")
def request_payment(order_public_id: str) -> None:
    log.info("payment.requested", extra={"order": order_public_id})

